#!/usr/bin/env python3
import json
import itertools
import copy

# Define the attribute lists
NAMES = {"Eric", "Peter", "Arnold", "Alice", "Bob"}
FOODS = {"stir fry", "spaghetti", "stew", "grilled cheese", "pizza"}
CARMODELS = {"ford f150", "tesla model 3", "bmw 3 series", "toyota camry", "honda civic"}
PHONEMODELS = {"iphone 13", "google pixel 6", "samsung galaxy s21", "oneplus 9", "huawei p50"}
OCCUPATIONS = {"teacher", "lawyer", "doctor", "artist", "engineer"}
DRINKS = {"tea", "milk", "water", "root beer", "coffee"}

def valid_partial(houses):
    """
    Checks all currently assigned houses (houses is a list of 5 elements; some may be None)
    against the puzzle constraints that can be verified.
    """
    # Check local constraints for each assigned house
    for i, h in enumerate(houses):
        if h is None:
            continue
        # C1: root beer <-> honda civic
        if h["Drink"] == "root beer" and h["CarModel"] != "honda civic":
            return False
        if h["CarModel"] == "honda civic" and h["Drink"] != "root beer":
            return False

        # C3: Alice <-> samsung galaxy s21
        if h["Name"] == "Alice" and h["PhoneModel"] != "samsung galaxy s21":
            return False
        if h["PhoneModel"] == "samsung galaxy s21" and h["Name"] != "Alice":
            return False

        # C4: Alice <-> stir fry
        if h["Name"] == "Alice" and h["Food"] != "stir fry":
            return False
        if h["Food"] == "stir fry" and h["Name"] != "Alice":
            return False

        # C19: grilled cheese <-> Peter
        if h["Food"] == "grilled cheese" and h["Name"] != "Peter":
            return False
        if h["Name"] == "Peter" and h["Food"] != "grilled cheese":
            return False

        # C7: doctor <-> Arnold
        if h["Occupation"] == "doctor" and h["Name"] != "Arnold":
            return False
        if h["Name"] == "Arnold" and h["Occupation"] != "doctor":
            return False

        # C16: Arnold <-> toyota camry
        if h["Name"] == "Arnold" and h["CarModel"] != "toyota camry":
            return False
        if h["CarModel"] == "toyota camry" and h["Name"] != "Arnold":
            return False

        # C8 & C10: iphone 13 <-> (coffee and stew)
        if h["PhoneModel"] == "iphone 13" and h["Drink"] != "coffee":
            return False
        if h["Drink"] == "coffee" and h["PhoneModel"] != "iphone 13":
            return False
        if h["PhoneModel"] == "iphone 13" and h["Food"] != "stew":
            return False
        if h["Food"] == "stew" and h["PhoneModel"] != "iphone 13":
            return False

        # C9: engineer <-> bmw 3 series
        if h["Occupation"] == "engineer" and h["CarModel"] != "bmw 3 series":
            return False
        if h["CarModel"] == "bmw 3 series" and h["Occupation"] != "engineer":
            return False

        # C18: oneplus 9 <-> lawyer
        if h["PhoneModel"] == "oneplus 9" and h["Occupation"] != "lawyer":
            return False
        if h["Occupation"] == "lawyer" and h["PhoneModel"] != "oneplus 9":
            return False

        # C13: google pixel 6 <-> tea
        if h["PhoneModel"] == "google pixel 6" and h["Drink"] != "tea":
            return False
        if h["Drink"] == "tea" and h["PhoneModel"] != "google pixel 6":
            return False

        # C5: tea cannot be in the fifth house (house index 4)
        if i == 4 and h["Drink"] == "tea":
            return False

        # C17: Eric is in the fourth house (house index 3)
        if i == 3 and h["Name"] != "Eric":
            return False

    # Check adjacent pairs constraints
    for i in range(1, len(houses)):
        if houses[i] is not None and houses[i-1] is not None:
            h_prev = houses[i-1]
            h_curr = houses[i]
            # C2: milk is immediately left of grilled cheese
            if h_prev["Drink"] == "milk" and h_curr["Food"] != "grilled cheese":
                return False
            if h_curr["Food"] == "grilled cheese" and h_prev["Drink"] != "milk":
                return False

            # C11: doctor is immediately left of oneplus 9
            if h_prev["Occupation"] == "doctor" and h_curr["PhoneModel"] != "oneplus 9":
                return False
            if h_curr["PhoneModel"] == "oneplus 9" and h_prev["Occupation"] != "doctor":
                return False

            # C12: honda civic is immediately left of spaghetti
            if h_prev["CarModel"] == "honda civic" and h_curr["Food"] != "spaghetti":
                return False
            if h_curr["Food"] == "spaghetti" and h_prev["CarModel"] != "honda civic":
                return False

    # Check ordering constraint C6: bmw 3 series is somewhere to the left of tea
    for i, h in enumerate(houses):
        if h is not None and h["Drink"] == "tea":
            # cannot be in the first house
            if i == 0:
                return False
            # There must be a house to its left with bmw 3 series.
            found = False
            for j in range(i):
                if houses[j] is not None and houses[j]["CarModel"] == "bmw 3 series":
                    found = True
                    break
            if not found:
                return False

    # Check ordering constraint C15: exactly one house between Alice and the owner of ford f150.
    alice_index = None
    ford_index = None
    for i, h in enumerate(houses):
        if h is not None:
            if h["Name"] == "Alice":
                alice_index = i
            if h["CarModel"] == "ford f150":
                ford_index = i
    if alice_index is not None and ford_index is not None:
        if abs(alice_index - ford_index) != 2:
            return False

    return True

def search(houses, index, available):
    """
    Recursively assign attributes to the houses from left (index 0) to right (index 4).
    houses: list of length 5 (some entries may be None). 
    available: dictionary with keys for each attribute holding the remaining possible values.
    """
    if index == 5:
        # All houses assigned; final check
        if valid_partial(houses):
            return houses
        else:
            return None

    # Iterate over all possible combinations for the current house from available values.
    for name in available["Name"]:
        # C17: House 4 (index 3) must be Eric.
        if index == 3 and name != "Eric":
            continue

        for food in available["Food"]:
            # C4 and C19: If name is Alice, food must be stir fry; if food is stir fry then name must be Alice.
            if name == "Alice" and food != "stir fry":
                continue
            if food == "stir fry" and name != "Alice":
                continue
            # Grilled cheese must go with Peter.
            if food == "grilled cheese" and name != "Peter":
                continue
            if name == "Peter" and food != "grilled cheese":
                continue

            for car in available["CarModel"]:
                # C16: Arnold <-> toyota camry.
                if name == "Arnold" and car != "toyota camry":
                    continue
                if car == "toyota camry" and name != "Arnold":
                    continue

                for phone in available["PhoneModel"]:
                    # C3: Alice <-> samsung galaxy s21.
                    if name == "Alice" and phone != "samsung galaxy s21":
                        continue
                    if phone == "samsung galaxy s21" and name != "Alice":
                        continue
                    # C10: stew <-> iphone 13.
                    if phone == "iphone 13" and food != "stew":
                        continue
                    if food == "stew" and phone != "iphone 13":
                        continue

                    for occupation in available["Occupation"]:
                        # C14: Alice <-> artist.
                        if name == "Alice" and occupation != "artist":
                            continue
                        if occupation == "artist" and name != "Alice":
                            continue
                        # C7: Arnold <-> doctor.
                        if name == "Arnold" and occupation != "doctor":
                            continue
                        if occupation == "doctor" and name != "Arnold":
                            continue
                        # C9: engineer <-> bmw 3 series.
                        if occupation == "engineer" and car != "bmw 3 series":
                            continue
                        if car == "bmw 3 series" and occupation != "engineer":
                            continue
                        # C18: lawyer <-> oneplus 9.
                        if occupation == "lawyer" and phone != "oneplus 9":
                            continue
                        if phone == "oneplus 9" and occupation != "lawyer":
                            continue

                        for drink in available["Drink"]:
                            # C8: iphone 13 <-> coffee.
                            if phone == "iphone 13" and drink != "coffee":
                                continue
                            if drink == "coffee" and phone != "iphone 13":
                                continue
                            # C13: google pixel 6 <-> tea.
                            if phone == "google pixel 6" and drink != "tea":
                                continue
                            if drink == "tea" and phone != "google pixel 6":
                                continue
                            # C1: root beer <-> honda civic.
                            if drink == "root beer" and car != "honda civic":
                                continue
                            if car == "honda civic" and drink != "root beer":
                                continue

                            candidate = {
                                "Name": name,
                                "Food": food,
                                "CarModel": car,
                                "PhoneModel": phone,
                                "Occupation": occupation,
                                "Drink": drink
                            }
                            new_houses = list(houses)
                            new_houses[index] = candidate
                            if not valid_partial(new_houses):
                                continue

                            # Create a new available set for the next recursion
                            new_available = { key: set(val) for key, val in available.items() }
                            new_available["Name"].remove(name)
                            new_available["Food"].remove(food)
                            new_available["CarModel"].remove(car)
                            new_available["PhoneModel"].remove(phone)
                            new_available["Occupation"].remove(occupation)
                            new_available["Drink"].remove(drink)

                            result = search(new_houses, index + 1, new_available)
                            if result is not None:
                                return result
    return None

def main():
    # Initialize houses (5 houses, indexed 0...4) with None
    houses = [None] * 5
    available = {
        "Name": set(NAMES),
        "Food": set(FOODS),
        "CarModel": set(CARMODELS),
        "PhoneModel": set(PHONEMODELS),
        "Occupation": set(OCCUPATIONS),
        "Drink": set(DRINKS)
    }

    solution = search(houses, 0, available)
    if solution is None:
        output = {"solution": {"header": ["House", "Name", "Food", "CarModel", "PhoneModel", "Occupation", "Drink"], "rows": []}}
    else:
        # Format the solution as required
        rows = []
        for i, house in enumerate(solution):
            row = [
                str(i+1),
                house["Name"],
                house["Food"],
                house["CarModel"],
                house["PhoneModel"],
                house["Occupation"],
                house["Drink"]
            ]
            rows.append(row)
        output = {"solution": {"header": ["House", "Name", "Food", "CarModel", "PhoneModel", "Occupation", "Drink"], "rows": rows}}
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
